rep('''/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  return orgRepo.archiveOrg(input.orgId);
}
''', '''const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug. The workspace is kept for
 * `DELETED_WORKSPACE_RETENTION_DAYS` so its owner can restore it; the
 * retention sweep purges it after that.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  assertNotArchived("Organization", input.orgId, org);

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  const archived = await orgRepo.archiveOrg(input.orgId);

  await emit("organization.deleted", {
    ...envelope(input.orgId, actor.userId),
    slug: archived.slug,
  });

  return archived;
}

/**
 * Brings a deleted workspace back. No `Actor` exists for a deleted workspace
 * (sign-in is refused), so the caller is identified by user id and must be an
 * owner of it. Restoring a live workspace is a no-op. A deleted workspace
 * whose window has closed is gone, whether or not the purge has run yet.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  const member = requireFound(
    await memberRepo.findMember(orgId, userId),
    "Organization",
    orgId,
  );

  assertCan(
    { userId, orgId, role: member.role },
    "org:restore",
    orgResource(orgId),
  );

  if (org.archivedAt === null) return org;

  const windowStart = toIsoTimestamp(
    new Date(Date.now() - DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY),
  );
  if (org.archivedAt <= windowStart) {
    throw new NotFoundError("Organization", orgId);
  }

  const restored = await orgRepo.restoreOrg(orgId);

  await emit("organization.restored", {
    ...envelope(orgId, userId),
    slug: restored.slug,
  });

  return restored;
}
''')
